  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "A flavone glycoside (camellianin B) was detected in rat brain after oral administration, demonstrating that glycosylated flavones can achieve CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Polar polyphenol glycosides including rutin and hyperoside were detected in rat brain after oral administration, supporting brain access for glycosylated flavonoids.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "Cyanidin-3-O-glucoside reached approximately 3.5 nmol/g in mouse brain after intraperitoneal injection, providing quantitative evidence of meaningful brain exposure for a glycosylated flavonoid.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Intact cyanidin 3-galactoside was observed in pig brain, supporting direct brain penetration of glycosylated anthocyanins rather than only metabolites.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a luteolin C-glucoside, a polar glycosylated flavonoid. Multiple in vivo studies demonstrate that glycosylated flavonoids and anthocyanins, despite high polarity, are detected in brain after systemic administration, indicating meaningful CNS access. The closest flavone glycoside evidence (camellianin B) supports transfer, so the prediction is pass.",
  "evidence_gaps": [
    "No direct quantitative brain exposure data for the exact C-glucosyl luteolin query molecule.",
    "Most evidence comes from O-glycosides and anthocyanins rather than C-glycosyl flavones.",
    "Some brain tissue detection studies may be confounded by residual blood contamination or metabolite interconversion."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

